 docker_images=array['tamland/airsonic-refix:latest']::text[],
 source_urls=array['https://hub.docker.com/r/tamland/airsonic-refix', 'https://github.com/tamland/airsonic-refix#readme', 'https://github.com/tamland/airsonic-refix/releases', 'https://github.com/tamland/airsonic-refix', 'https://github.com/tamland/airsonic-refix/blob/master/README.md']::text[],
 options='[{"label":"Maintainer Docker image","method":"docker","support_level":"official","image":"tamland/airsonic-refix:latest","url":"https://hub.docker.com/r/tamland/airsonic-refix","source_url":"https://github.com/tamland/airsonic-refix#readme","note":"Static frontend that connects to a separately hosted Subsonic-compatible music server.","sort_order":10},{"label":"Prebuilt web bundle","method":"native","support_level":"official","url":"https://github.com/tamland/airsonic-refix/releases","source_url":"https://github.com/tamland/airsonic-refix#readme","note":"Serve the built web files with a web server.","sort_order":30}]'::jsonb,
 checked_at=now(),
 updated_at=now()
where app_id=(select id from public.self_host_apps where slug='airsonic-refix-ui');

do $post_update_guard$
begin
 if (select count(*) from public.self_host_apps where slug in ('agora', 'agoracosmica', 'agorakit', 'agregarr', 'aimeos', 'aiometadata', 'aiostreams', 'airbridge', 'airbyte', 'airconnect', 'airdcpp', 'airpipe', 'airsonic', 'airsonic-advanced', 'airsonic-refix-ui') and published=true and self_hosting_status='self_hostable') <> 15 then raise exception 'Batch 24 app corrections failed'; end if;
 if (select count(*) from public.self_host_app_resource_estimates e join public.self_host_apps a on a.id=e.app_id where a.slug in ('agora', 'agoracosmica', 'agorakit', 'agregarr', 'aimeos', 'aiometadata', 'aiostreams', 'airbridge', 'airbyte', 'airconnect', 'airdcpp', 'airflow', 'airpipe', 'airsonic', 'airsonic-advanced', 'airsonic-refix-ui') and e.ram_estimate_kind='estimated' and e.storage_estimate_kind='estimated' and e.ram_estimate_basis is not null and e.storage_estimate_basis is not null) <> 16 then raise exception 'Batch 24 estimates check failed'; end if;
 if not exists(select 1 from public.self_host_apps where slug='airflow' and published=false) then raise exception 'airflow duplicate cleanup failed'; end if;
end;
$post_update_guard$;
commit;
